function dn14NaturalRockAtlas(c){const moon=DN14.assets.moon,mars=DN14.assets.mars;if(moon){dn14PhotoRock(c,moon,0,75,535,245,145,0);dn14PhotoRock(c,moon,1,514,583,114,89,1);}if(mars)dn14PhotoRock(c,mars,2,592,577,135,89,2);}
function dn14PhotoRock(c,image,slot,sx,sy,sw,sh,kind){c.save();c.clearRect(slot*320,0,320,320);c.translate(slot*320,0);dn14Bloom(c,165,258,137,18,kind===2?'#492d33':'#383746',.25);const w=Math.min(256,176*sw/sh),h=w*sh/sw,x=160-w*.5,y=254-h;c.save();c.translate(x,y);c.scale(w,h);const mask=new Path2D();mask.moveTo(.025,.94);mask.lineTo(.06,.67);mask.lineTo(.12,.49);mask.lineTo(.23,.34);mask.lineTo(.29,.14);mask.lineTo(.43,.05);mask.lineTo(.52,.12);mask.lineTo(.64,.04);mask.lineTo(.78,.13);mask.lineTo(.85,.32);mask.lineTo(.88,.58);mask.lineTo(.98,.91);mask.lineTo(.91,.98);mask.lineTo(.72,.95);mask.lineTo(.52,1);mask.lineTo(.27,.97);mask.closePath();c.clip(mask);c.drawImage(image,sx,sy,sw,sh,0,0,1,1);c.restore();c.restore();}

function dn14NearMaterial(c,r){const moon=r===1;c.save();for(let j=0;j<2600;j++){const x=dn14Hash(j*67+r)*512,y=dn14Hash(j*97+r)*400,size=.28+dn14Hash(j*43)*1.05;c.fillStyle=j%3?(moon?'#e0d4bd1a':'#f2c18e18'):(moon?'#39435b19':'#5533411c');c.fillRect(x,y,size*(1+dn14Hash(j*7)*.8),size*.65);}for(let j=0;j<45;j++){const x=dn14Hash(j*53+r)*512,y=dn14Hash(j*71+r)*380,rx=4+dn14Hash(j*37)*15,ry=1+dn14Hash(j*13)*3;dn14Oval(c,x,y,rx,ry,j%2?(moon?'#e8dfc608':'#eac19809'):(moon?'#39455b0a':'#57364509'));}for(let k=0;k<6;k++){const y=23+k*48;c.strokeStyle=k%2?(moon?'#e8dcc00b':'#f1c3910b'):(moon?'#3d495d0b':'#603c4b0a');c.lineWidth=7+k%3*3;c.beginPath();for(let x=0;x<=512;x+=8){const yy=y+Math.sin(x/512*DN14_TAU*2+k*.7)*4+Math.sin(x/512*DN14_TAU*5)*.9;x?c.lineTo(x,yy):c.moveTo(x,yy);}c.stroke();}c.restore();}
